-- =====================================================================
-- Enjoy PC Restaurante — Carga inicial
--
-- Ejecutar DESPUÉS de 03-storage.sql.
--
-- Es idempotente: se puede volver a ejecutar sin duplicar filas (usa
-- `on conflict`, que además actualiza las filas ya existentes).
--
-- MENÚ — datos REALES. Las 21 categorías y los 259 platos salen de la
-- carta oficial del restaurante (https://enjoyrestaurante.qrfy.do/),
-- con precios en RD$, descripciones ES/EN y las fotos del propio
-- restaurante alojadas en el bucket `media` de Storage. Esta sección se
-- generó desde la base de datos en producción, así que la refleja tal
-- cual; si cambias el menú desde el panel, vuelve a exportarla antes de
-- usar este archivo para montar un proyecto nuevo.
--
-- ⚠️ EVENTOS — los DÍAS/HORARIOS siguen siendo estimaciones, no datos
-- confirmados por el negocio. Ver CLAUDE.md. El panel de administración
-- existe precisamente para corregirlos.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Categorías del menú (las 21 de la carta real)
-- ---------------------------------------------------------------------
on conflict (id) do update set
  label_es = excluded.label_es,
  label_en = excluded.label_en,
  orden    = excluded.orden;

-- ---------------------------------------------------------------------
-- Platos y bebidas (259 de la carta real)
--
-- `activo = false` en los dos que la carta no publica con precio
-- (French Croissant y Paella Mixta): no se inventa un precio; el dueño
-- los activa desde el panel cuando lo tenga.
-- ---------------------------------------------------------------------
on conflict (slug) do update set
  category  = excluded.category,
  nombre_es = excluded.nombre_es,
  nombre_en = excluded.nombre_en,
  desc_es   = excluded.desc_es,
  desc_en   = excluded.desc_en,
  precio    = excluded.precio,
  img       = excluded.img,
  tags      = excluded.tags,
  orden     = excluded.orden,
  activo    = excluded.activo;

-- ---------------------------------------------------------------------
-- Eventos semanales (7 — uno por día, tal como están hoy)
--
-- A diferencia del archivo JS original, el esquema permite añadir más de
-- uno por día o dejar días vacíos. Esto es solo el punto de partida.
--
-- dia: 0=domingo, 1=lunes ... 6=sábado (índice de Date.getDay())
-- ---------------------------------------------------------------------
   'Música en vivo', 'Live music',
